(function(win) {
	// boot 영역

	var _pageReadyFunctionHolder = [];
	var _page = {};
	_page._componentHolder = {};
	_page._htmlTemplateHolder = {};
	_page._$htmlTemplateStorage = $("<div/>");

	_page.onReady = function(func) {
		_pageReadyFunctionHolder.push(func);
	};

	_page.addComponent = function(id, component) {
		this._componentHolder[id] = component;
	};

	/**
	id속성에 대응하는 컴포넌트 객체를 반환한다.
	 */
	_page.getComponent = function(elementId) {
		return Page._componentHolder[elementId];
	};
	/**
	url 쿼리스트링 파싱
	*/
	_page.parseQueryString = function(str) {
		var queryParams = {};
		var queryString;
		if(!str || typeof str !== 'string') {
			return queryParams;
		}
		queryStartIndex = str.indexOf('?');
		if (queryStartIndex > -1){
			queryString = str.substring(queryStartIndex +1 );
		} else {
			queryString = str; 
		}
		
		var queryPairs = queryString.split('&');
		var pair, key, value
		for (var i = 0; i < queryPairs.length; i++) {
			pair = queryPairs[i].split('=');
			key = decodeURIComponent(pair[0] || '');
			value = decodeURIComponent(pair[1] || '');

			if (queryParams[key]) {
				//이미 같은 키 값이 존재할 경우 배열로 저장
				if (!Array.isArray(queryParams[key])) {
					queryParams[key] = [queryParams[key]];
				};
				queryParams[key].push(value);
			} else {
				queryParams[key] = value;
			}
		}
		
		return queryParams;
	}
	
	
	/**
	현재 창의 URL 쿼리 문자열에서 쿼리 매개변수를 가져오는 함수
	 */
	_page.getParameter = function(str) {
		var queryString = window.location.search;
		var queryParams = Page.parseQueryString(queryString);

		return str ? queryParams[str] : queryParams; 
	};

	/** 페이지를 이동한다. */
	_page.move = function(uri, param) {
		location.href = uri + ((!param) ? "" : "?" + $.param(param));
	};
	
	/** 새 페이지를 오픈한다. */
	_page.openWindow = function(uri, param, opt) {
		if(opt){
			window.open(uri + ((!param) ? "" : "?" + $.param(param)), '_blank', opt);	
		}else{
			window.open(uri + ((!param) ? "" : "?" + $.param(param)), '_blank');
		}
		
	};

	/** start of HTML 템플릿 관련 */
	_page.prepareHtmlTemplate = function(target) {
		if (!_page._htmlTemplateHolder[target]) _page._htmlTemplateHolder[target] = {};
		_page._htmlTemplateHolder[target].uri = "/js/common/html/" + target + ".html";
		_page._htmlTemplateHolder[target].html = null;
	};
	_page._getHtmlTemplateObj = function() {
		return _page._htmlTemplateHolder;
	};
	_page.getHtmlTemplateById = function(id) {
		return _page._$htmlTemplateStorage.find("#" + id).html();
	};
	/** end of HTML 템플릿 관련 */

	/* 알러트창을 띄운다 */
	_page.alert = function(msg, onClose, onDestroy) {
		var instantAlertId = "ALERT_MSG_" + new Date().getTime();

		var tmplStr = _page.getHtmlTemplateById("alert_template");
		var hb = Handlebars.compile(tmplStr);

		Handlebars.registerHelper('alert', function(text) {
			var replacedText = text.replace(/\n/g, '<br>');
			return new Handlebars.SafeString(replacedText);
		});

		var html = hb({ msg: msg });
		var $html = $(html).attr("id", instantAlertId);


		$("body").append($html);

		$("#" + instantAlertId).dialog({
			title: "알림",
			dialogClass: "modal_alert",
			resizable: false,
			width: 550,
			height: "auto",
			modal: true,
			autoOpen: true,
			draggable: false,
			// buttons custom
			buttons: [
				{
					text: "확인",
					class: "btn btn_primary	",
					click: function() {
						try {
							if (typeof onClose == 'function') {
								onClose();
							}
						} finally {
							$(this).dialog("close");
							$(this).dialog("destroy");
							$("#" + instantAlertId).remove();
							if (typeof onDestroy == 'function') {
								onDestroy();
							}
						}
					}
				}
			]
		});
	};

	/* 컨펌창을 띄운다 */
